  [4731] = { "飼いならした熊にEnraging Biteのアビリティを教えます。Enraging Biteは敵の物理攻撃への耐性を下げ、さらにその注意を引きつけます。\n必要条件：\nペットのLevel 13以上", nil, 0xaa9eb026, nil, "um" },
  [4732] = { "飼いならした熊にRoar of Fortitudeのアビリティを教えます。Roar of Fortitudeはパーティー全員の最大体力を増加させます。\n必要条件：\nペットのLevel 36以上", nil, 0x1c13d922, nil, "um" },
  [4733] = { "飼いならした猪にGoreのアビリティを教えます。Goreは敵に物理の継続ダメージを与えます。\n必要条件：\nペットのLevel 13以上", nil, 0x6b6d5fe0, nil, "um" },
  [4734] = { "飼いならした猪にToughen Hideのアビリティを教えます。Toughen Hideは物理攻撃への耐性を高めます。\n必要条件：\nペットのLevel 22以上", nil, 0x38bf9609, nil, "um" },
  [4735] = { "飼いならした猪にVital Woundのアビリティを教えます。Vital Woundは敵の攻撃速度を低下させます。\n必要条件：\nペットのLevel 36以上", nil, 0x72e2e4a8, nil, "um" },
  [4736] = { "飼いならした鳥にFlight of the Peregrineのアビリティを教えます。Flight of the Peregrineは鳥の移動速度を増加させます。\n必要条件：\nペットのLevel 13以上", nil, 0x44d34f6f, nil, "um" },
  [4737] = { "飼いならした鳥にEye Peckのアビリティを教えます。Eye Peckは敵が戦闘で攻撃を外しやすくします。\n必要条件：\nペットのLevel 22以上", nil, 0x30da3f71, nil, "um" },
  [4740] = { "飼いならした猫にFerocityのアビリティを教えます。Ferocityは猫の攻撃速度を増加させますが、その代わりに物理攻撃で受けるダメージが増えます。\n必要条件：\nペットのLevel 13以上", nil, 0xb25f5e2b, nil, "um" },
  [4741] = { "飼いならした猫にOpen Woundのアビリティを教えます。Open Woundは敵に物理の継続ダメージを与え、さらに短時間、物理攻撃で受けるダメージを増加させます。\n必要条件：\nペットのLevel 36以上", nil, 0xc0a030b9, nil, "um" },
  [4742] = { "飼いならしたカニにTough Shellのアビリティを教えます。Tough Shellは、攻撃を受けた際にカニのアーマー値が増加する確率を与えます。\n必要条件：\nペットのLevel 13以上", nil, 0xa61ec09a, nil, "um" },
