  [4744] = { "飼いならしたカニにTough Shellのアビリティを教えます。Tough Shellは、攻撃を受けた際にカニのアーマー値が増加する確率を与えます。\n必要条件：\nペットのLevel 28以上", nil, 0xa61f0632, nil, "um" },
  [4745] = { "飼いならしたカニにTough Shellのアビリティを教えます。Tough Shellは、攻撃を受けた際にカニのアーマー値が増加する確率を与えます。\n必要条件：\nペットのLevel 36以上", nil, 0xa61f4835, nil, "um" },
  [4746] = { "飼いならしたカニにTight Pinchのアビリティを教えます。Tight Pinchはカニの次の攻撃に追加ダメージを与え、さらに敵をスタンさせます。\n必要条件：\nペットのLevel 22以上", nil, 0x223cab29, nil, "um" },
  [4747] = { "飼いならしたカニにClenched Pinchersのアビリティを教えます。Clenched Pinchersは敵をその場に拘束しながら物理の継続ダメージを与えます。敵を拘束している間、カニは攻撃もほかの行動もできません。\n必要条件：\nペットのLevel 36以上", nil, 0x2623d934, nil, "um" },
  [4748] = { "飼いならしたcrociliskにQuick Snapのアビリティを教えます。Quick Snapは、攻撃を受けた際にcrociliskが反撃する確率を与えます。\n必要条件：\nペットのLevel 22以上", nil, 0xdab0c6cb, nil, "um" },
