  [4932] = { "術者を魔法ダメージに対して無敵にし、受けるPhysicalダメージを$N1減少させ、攻撃を受けるとPrismatic Exileを召喚させます。効果時間は$D1です。", "魔法ダメージに対する免疫があります。\n受ける物理ダメージが$N1減少しています。\n攻撃を受けるとPrismatic Exileを召喚します。", 0xdb88f109, 0xd0d18186, "uu" },
  [4937] = { "$D1の間、術者を戦闘で援護するPrismatic Exileを$N1体召喚します。", nil, 0x71d9c6a7, nil, "um" },
  [4938] = { "周囲の敵に通常ダメージに加えて$N1を与えます。", nil, 0x301ad2a4, nil, "um" },
  [4941] = { "$D1の間、アーマーを$N1増加させます。", "アーマーが上昇しています。", 0x92291afa, 0xd44e6a60, "uu" },
  [4942] = { "15秒間、アーマーを1000増加します。", nil, 0x5e7de11e, nil, "um" },
  [4945] = { "覚悟があるなら、Seaworn Altarに置いてください……", nil, 0xfec61d7b, nil, "um" },
  [4947] = { "破壊的な力を解き放ちます", nil, 0xb3b2c432, nil, "um" },
  [4948] = { "$D1の間熊に変身し、アーマーとヒットポイントを増加させ、さまざまな熊のアビリティを使えるようにします。", "熊に変身しています。\nアーマーと体力が増加しています。", 0x1c95e4b3, 0xc6f6899b, "uu" },
  [4950] = { "$D1の間、術者を戦闘で援護するPuppet of Helcularを$N1体召喚します。", nil, 0x6ca7e137, nil, "um" },
  [4951] = { "術者がダメージを受けた際、味方を召喚する確率を追加します。", nil, 0x8869a310, nil, "um" },
  [4952] = { "$D1の間、術者の主人を透明にしますが、その代わりに主人は攻撃できなくなります。", nil, 0xc5167b89, nil, "um" },
  [4954] = { "炉の近くで右クリックすると壊せます。", nil, 0x79d3ef8d, nil, "um" },
  [4955] = { "$D1の間、術者は攻撃ごとに$N1の追加ダメージを与えるようになりますが、移動速度が$N3%低下し、攻撃間隔が$N4%延びます。", "与える物理ダメージが$N1増加しています。\n移動速度が$N2%低下しています。\n攻撃間隔が$N3%長くなっています。", 0x73b5dadb, 0xcb810a67, "uu" },
  [4960] = { "Potion of Fervorを作成します。", nil, 0x467416f4, nil, "um" },
  [4961] = { "味方の体力を$N1回復します。", nil, 0xe7891914, nil, "um" },
  [4962] = { "敵を動けなくし、$D1の間攻撃間隔を$N1%延ばします。", "移動できません。\n攻撃間隔が$N1%長くなっています。", 0xe3989a9c, 0xc9bc6968, "uu" },
  [4970] = { nil, "$D1ごとに$N1のダメージを回復しています。", nil, 0x8d136749, "mu" },
  [4971] = { "$D1持続し、周囲の範囲にいる味方を定期的に回復するワードを召喚します。", nil, 0x5f5c01ed, nil, "um" },
  [4974] = { "$D1の間、敵のスタミナを$N1、精神を$N2低下させます。", "スタミナが$N1低下しています。\n精神が$N2低下しています。", 0xc08ba96f, 0x9f460a0c, "uu" },
  [4975] = { "Winterhoofの浄化の精霊を呼び出します。", nil, 0x8e19d44f, nil, "um" },
  [4976] = { "右クリックすると、ShadowglenのムーンウェルでCrystal Phialを満たします。", nil, 0x591bd331, nil, "um" },
